import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for i in range(3, math.isqrt(n) + 1, 2):
        if n % i == 0:
            return False
    return True
```

Uses `math.isqrt(n)` for an exact integer square root, so it checks divisors only up to `sqrt(n)`.
